'use strict';

var randu = require( '@stdlib/random/base/randu' );
var incrnanwmean = require( './../lib' );

var accumulator;
var mean;
var v;
var w;
var i;

accumulator = incrnanwmean();

console.log( '\nValue\tWeight\tMean\n' );
for ( i = 0; i < 100; i++ ) {
	if ( randu() < 0.2 ) {
		v = NaN;
		w = NaN;
	} else {
		v = randu() * 100.0;
		w = randu() * 10.0;
	}
	mean = accumulator( v, w );
	console.log( '%d\t%d\t%d', v.toFixed( 4 ), w.toFixed( 4 ), ( mean === null ) ? NaN : mean.toFixed( 4 ) );
}
console.log( '\nFinal weighted mean: %d\n', accumulator() );
